const sqlite3 = require('/usr/local/lib/node_modules/n8n/node_modules/sqlite3');

return new Promise((resolve, reject) => {
  const db = new sqlite3.Database('/calibre-library/metadata.db', sqlite3.OPEN_READONLY, (err) => {
    if (err) return reject(new Error('Cannot open Calibre DB: ' + err.message));

    const queryBooks = `SELECT b.id, b.title, b.timestamp, b.series_index, b.path, b.has_cover,
      GROUP_CONCAT(DISTINCT a.name) as authors, GROUP_CONCAT(DISTINCT t.name) as tags,
      s.name as series, p.name as publisher, r.rating
      FROM books b
      LEFT JOIN books_authors_link bal ON b.id = bal.book
      LEFT JOIN authors a ON bal.author = a.id
      LEFT JOIN books_tags_link btl ON b.id = btl.book
      LEFT JOIN tags t ON btl.tag = t.id
      LEFT JOIN books_series_link bsl ON b.id = bsl.book
      LEFT JOIN series s ON bsl.series = s.id
      LEFT JOIN books_publishers_link bpl ON b.id = bpl.book
      LEFT JOIN publishers p ON bpl.publisher = p.id
      LEFT JOIN books_ratings_link brl ON b.id = brl.book
      LEFT JOIN ratings r ON brl.rating = r.id
      GROUP BY b.id`;

    const queryFormats = 'SELECT book, format, uncompressed_size FROM data';

    db.all(queryBooks, (err, books) => {
      if (err) { db.close(); return reject(new Error('Books query failed: ' + err.message)); }

      db.all(queryFormats, (err, formats) => {
        db.close();
        if (err) return reject(new Error('Formats query failed: ' + err.message));

        const sizeMap = {};
        const fmtMap = {};
        for (const f of formats) {
          sizeMap[f.book] = (sizeMap[f.book] || 0) + (f.uncompressed_size || 0);
          if (!fmtMap[f.book]) fmtMap[f.book] = [];
          fmtMap[f.book].push(f.format);
        }

        const result = books.map(b => ({
          json: {
            id: b.id,
            title: b.title || 'Unknown',
            authors: b.authors || '',
            tags: b.tags || '',
            series: b.series || '',
            seriesIndex: b.series_index || null,
            publisher: b.publisher || '',
            timestamp: b.timestamp || null,
            rating: b.rating ? b.rating / 2 : null,
            hasCover: b.has_cover === 1,
            path: b.path || '',
            formats: fmtMap[b.id] || [],
            totalSizeBytes: sizeMap[b.id] || 0
          }
        }));

        resolve(result);
      });
    });
  });
});

const calibreBooks = $('Read Calibre DB').all();
const notionPages = $('Query Existing Notion Entries').first().json.results || [];

const existingIds = new Map();
for (const page of notionPages) {
  const calId = page.properties?.['Calibre ID']?.number;
  if (calId) existingIds.set(calId, page.id);
}

const toCreate = [];
const toUpdate = [];
for (const item of calibreBooks) {
  const b = item.json;
  if (existingIds.has(b.id)) {
    toUpdate.push({ ...b, notionPageId: existingIds.get(b.id) });
  } else {
    toCreate.push(b);
  }
}

return [{ json: { toCreate, toUpdate, stats: { total: calibreBooks.length, new: toCreate.length, existing: toUpdate.length } } }];

const { toCreate, stats } = $input.first().json;
const notionToken = $env.NOTION_TOKEN;
const dbId = '3da63d55-66c5-8133-a230-cdc65171d864';
let created = 0, errors = 0;

for (const b of toCreate) {
  try {
    const body = {
      parent: { database_id: dbId },
      properties: {
        'Title': { title: [{ text: { content: (b.title || '').slice(0, 200) } }] },
        'Author': { rich_text: [{ text: { content: (b.authors || '').slice(0, 200) } }] },
        'Format': { multi_select: (b.formats || []).map(f => ({ name: f })) },
        'Tags': { multi_select: (b.tags || '').split(',').filter(t => t.trim()).map(t => ({ name: t.trim().slice(0, 100) })) },
        'Series': { rich_text: [{ text: { content: (b.series || '').slice(0, 200) } }] },
        'Series Index': { number: b.seriesIndex },
        'Publisher': { rich_text: [{ text: { content: (b.publisher || '').slice(0, 200) } }] },
        'Date Added': b.timestamp ? { date: { start: new Date(b.timestamp).toISOString().split('T')[0] } } : { date: null },
        'Rating': { number: b.rating },
        'File Size MB': { number: Math.round(b.totalSizeBytes / 1048576) },
        'Has Cover': { checkbox: b.hasCover },
        'Calibre ID': { number: b.id },
        'File Path': { rich_text: [{ text: { content: (b.path || '').slice(0, 200) } }] },
        'Status': { select: { name: 'Unread' } }
      }
    };
    const resp = await fetch('https://api.notion.com/v1/pages', {
      method: 'POST',
      headers: { 'Authorization': notionToken, 'Notion-Version': '2022-06-28', 'Content-Type': 'application/json' },
      body: JSON.stringify(body)
    });
    if (resp.ok) created++; else errors++;
  } catch (e) { errors++; }
}

return [{ json: { created, unchanged: stats.existing, errors, total: stats.total } }];

const result = $input.first().json;
console.log(`Books Sync: ${result.created} created, ${result.unchanged} unchanged, ${result.errors} errors (${result.total} total books)`);
return [{ json: result }];
